    private static final List<Entry> ALL;
    private static final Map<String, String> EXTENSION_OWNER = new LinkedHashMap<>();

    static {
        List<Entry> all = new ArrayList<>(SAMPLE);
        all.addAll(MORE);
        ALL = Collections.unmodifiableList(all);
        for (Entry e : ALL) {
            EXTENSION_OWNER.putIfAbsent(e.extension(), e.id());
        }
        for (Entry e : ALL) {
            e.extraExtensions().forEach(x -> EXTENSION_OWNER.putIfAbsent(x, e.id()));
        }
    }

    private static final Pattern OBJC = Pattern.compile("(?m)^\\s*(#import\\b|@interface\\b|@implementation\\b|@end\\b)|\\[\\w+\\s+\\w+[:\\]]");
    private static final Pattern PROLOG = Pattern.compile("(?m)^\\s*:-|^[a-z]\\w*\\([^)]*\\)\\s*:-");
    private static final Pattern PERL = Pattern.compile("(?m)\\b(my|use|sub|print)\\b|\\$\\w+");

    private LanguageCatalog() {
    }

    private static Entry sample(String id, String name, String ext, String run, List<String> aliases, List<String> extra) {
        return new Entry(new ProgrammingLanguage(id, name, ext, run, aliases), true, extra, id, "", "", "", "", "");
    }

    private static Entry more(String id, String name, String ext, String run, List<String> aliases, List<String> extra,
                              String fence, String unit, String src, String test, String check, String image) {
        return new Entry(new ProgrammingLanguage(id, name, ext, run, aliases), false, extra, fence, unit, src, test,
                check, image);
    }

    /** All languages: the sample languages first, then the AI-only ones. */
    public static List<Entry> entries() {
        return ALL;
    }

    /** The 15 languages with hand-written sample programs. */
    public static List<ProgrammingLanguage> sampleLanguages() {
        return SAMPLE.stream().map(Entry::language).toList();
    }

    /** Languages converted and generated by the AI model only. */
    public static List<ProgrammingLanguage> moreLanguages() {
        return MORE.stream().map(Entry::language).toList();
    }

    public static List<ProgrammingLanguage> allLanguages() {
        return ALL.stream().map(Entry::language).toList();
    }

    /**
     * Resolves a language by id, then display name, then alias, then main file extension (case-insensitive), so an
     * id always wins over another language's alias or extension.
     */
    public static Optional<Entry> find(String value) {
        if (value == null || value.isBlank()) {
            return Optional.empty();
        }
        String key = value.trim().toLowerCase(Locale.ROOT);
        String noDot = key.startsWith(".") ? key.substring(1) : key;
        for (Entry e : ALL) {
            if (e.id().equals(key)) {
                return Optional.of(e);
            }
        }
        for (Entry e : ALL) {
            if (e.name().toLowerCase(Locale.ROOT).equals(key)) {
                return Optional.of(e);
            }
        }
        for (Entry e : ALL) {
            if (e.language().aliases().contains(key)) {
                return Optional.of(e);
            }
        }
        for (Entry e : ALL) {
            if (e.extension().equals(noDot)) {
                return Optional.of(e);
            }
        }
        return Optional.empty();
    }

    /**
     * Language of a source file from its extension. {@code .m} is MATLAB unless the content looks like Objective-C,
     * {@code .pl} is Perl unless it looks like Prolog, and {@code .cls} is Apex unless it is a VB6 class module.
     *
     * @param content read lazily, only for the ambiguous extensions
     */
    public static Optional<Entry> forFile(String fileName, Supplier<String> content) {
        if (fileName == null) {
            return Optional.empty();
        }
        int dot = fileName.lastIndexOf('.');
        if (dot < 0 || dot == fileName.length() - 1) {
            return Optional.empty();
        }
        String ext = fileName.substring(dot + 1).toLowerCase(Locale.ROOT);
        String owner = EXTENSION_OWNER.get(ext);
        if (owner == null) {
            return Optional.empty();
        }
        String id = switch (ext) {
            case "m" -> OBJC.matcher(text(content)).find() ? "objective-c" : "matlab";
            case "pl" -> {
                String code = text(content);
                yield PROLOG.matcher(code).find() && !PERL.matcher(code).find() ? "prolog" : "perl";
            }
            case "cls" -> text(content).stripLeading().startsWith("VERSION 1.0 CLASS") ? "vb6" : "apex";
            default -> owner;
        };
        return ALL.stream().filter(e -> e.id().equals(id)).findFirst();
    }

    /** Every recognised source-file extension, with a leading dot. */
    public static List<String> extensions() {
        return EXTENSION_OWNER.keySet().stream().map(x -> "." + x).toList();
    }

    private static String text(Supplier<String> content) {
        try {
            String s = content == null ? null : content.get();
            return s == null ? "" : s;
        } catch (RuntimeException e) {
            return "";
        }
    }
